const std = @import("std");
const GPUCoordinator = @import("gpu_coordinator.zig").GPUCoordinator;
const MGT = @import("../tokenizer/mgt.zig").MGT;
const accel = @import("../hw/accel/accel_interface.zig");
const RSFAccelerator = accel.RSFAccelerator;
const PinnedMemory = accel.PinnedMemory;

const LOSS_BUFFER_ITEMS: usize = 2;
const DEFAULT_LOG_INTERVAL: usize = 100;
const DEFAULT_PAD_ID: u32 = 0;
const DEFAULT_CHECKPOINT_PERMS: u32 = 0o600;
const CHECKPOINT_MAGIC: u32 = 0x46555448;
const MAX_LINE_SIZE: usize = 1024 * 1024;
const MAX_TEXT_SIZE: usize = 1024 * 1024;
const MAX_JSON_ITERATIONS: usize = 100000;

pub const TrainerConfig = struct {
    learning_rate: f32,
    momentum: f32,
    max_line_size: usize,
    max_text_size: usize,
    checkpoint_version: u32,
    log_interval: usize,
    pad_id: u32,
    deny_relative_paths: bool,
    vocab: []const []const u8,
    anchors: []const []const u8,
};

pub const DistributedTrainerFuthark = struct {
    allocator: std.mem.Allocator,
    coordinator: *GPUCoordinator,
    tokenizer: MGT,
    accelerator: RSFAccelerator,
    model_dim: usize,
    local_batch_size: usize,
    global_step: usize,
    learning_rate: f32,
    momentum: f32,
    max_line_size: usize,
    max_text_size: usize,
    checkpoint_version: u32,
    log_interval: usize,
    pad_id: u32,
    deny_relative_paths: bool,
    loss_buffer_bytes: []u8,

    pub fn init(
        allocator: std.mem.Allocator,
        coordinator: *GPUCoordinator,
        model_dim: usize,
        local_batch_size: usize,
        vocab: []const []const u8,
        anchors: []const []const u8,
    ) !DistributedTrainerFuthark {
        return initWithConfig(allocator, coordinator, model_dim, local_batch_size, TrainerConfig{
            .learning_rate = 0.001,
            .momentum = 0.9,
            .max_line_size = MAX_LINE_SIZE,
            .max_text_size = MAX_TEXT_SIZE,
            .checkpoint_version = 1,
            .log_interval = DEFAULT_LOG_INTERVAL,
            .pad_id = DEFAULT_PAD_ID,
            .deny_relative_paths = true,
            .vocab = vocab,
            .anchors = anchors,
        });
    }

    pub fn initWithConfig(
        allocator: std.mem.Allocator,
        coordinator: *GPUCoordinator,
        model_dim: usize,
        local_batch_size: usize,
        config: TrainerConfig,
    ) !DistributedTrainerFuthark {
        if (model_dim == 0) return error.InvalidModelDim;
        if (local_batch_size == 0) return error.InvalidBatchSize;
        if (coordinator.world_size == 0) return error.InvalidWorldSize;
        if (coordinator.rank >= coordinator.world_size) return error.InvalidRank;
        if (@isNan(config.learning_rate) or !std.math.isFinite(config.learning_rate) or config.learning_rate <= 0) return error.InvalidLearningRate;
        if (@isNan(config.momentum) or !std.math.isFinite(config.momentum) or config.momentum < 0 or config.momentum >= 1.0) return error.InvalidMomentum;
        if (config.vocab.len == 0) return error.EmptyVocab;

        const max_model_dim: usize = 65536;
        if (model_dim > max_model_dim) return error.ModelDimTooLarge;

        const weight_count = std.math.mul(usize, model_dim, model_dim) catch return error.ModelDimTooLarge;
        _ = weight_count;

        var tokenizer = try MGT.init(allocator, config.vocab, config.anchors);
        errdefer tokenizer.deinit();

        var accelerator = try RSFAccelerator.init(model_dim);
        errdefer accelerator.deinit();

        const loss_buffer_size = LOSS_BUFFER_ITEMS * @sizeOf(f32);
        const raw_loss_buffer = try coordinator.allocDeviceMemory(loss_buffer_size);
        errdefer coordinator.freeDeviceMemory(raw_loss_buffer);

        if (raw_loss_buffer.len != loss_buffer_size) return error.DeviceAllocationFailed;

        return DistributedTrainerFuthark{
            .allocator = allocator,
            .coordinator = coordinator,
            .tokenizer = tokenizer,
            .accelerator = accelerator,
            .model_dim = model_dim,
            .local_batch_size = local_batch_size,
            .global_step = 0,
            .learning_rate = config.learning_rate,
            .momentum = config.momentum,
            .max_line_size = config.max_line_size,
            .max_text_size = config.max_text_size,
            .checkpoint_version = config.checkpoint_version,
            .log_interval = config.log_interval,
            .pad_id = config.pad_id,
            .deny_relative_paths = config.deny_relative_paths,
            .loss_buffer_bytes = raw_loss_buffer,
        };
    }

    pub fn deinit(self: *DistributedTrainerFuthark) void {
        self.coordinator.freeDeviceMemory(self.loss_buffer_bytes);
        self.accelerator.deinit();
        self.tokenizer.deinit();
    }

    fn validatePathPolicy(self: *const DistributedTrainerFuthark, path: []const u8) !void {
        if (path.len == 0) return error.EmptyPath;
        if (!self.deny_relative_paths) return;
        if (!std.fs.path.isAbsolute(path)) return error.RelativePathDenied;
        var it = std.mem.splitScalar(u8, path, std.fs.path.sep);
        while (it.next()) |component| {
            if (std.mem.eql(u8, component, "..")) return error.PathTraversalDenied;
        }
    }

    fn openDatasetFile(self: *DistributedTrainerFuthark, dataset_path_raw: []const u8) !std.fs.File {
        const dataset_path = std.mem.trim(u8, dataset_path_raw, &std.ascii.whitespace);
        try self.validatePathPolicy(dataset_path);
        const safe_path = try self.allocator.dupe(u8, dataset_path);
        defer self.allocator.free(safe_path);
        const file = std.fs.cwd().openFile(safe_path, .{ .mode = .read_only }) catch |err| {
            return err;
        };
        return file;
    }

    pub fn loadDataset(self: *DistributedTrainerFuthark, dataset_path: []const u8) ![][]const u8 {
        if (self.coordinator.world_size == 0) return error.InvalidWorldSize;
        if (self.coordinator.rank >= self.coordinator.world_size) return error.InvalidRank;

        var file = try self.openDatasetFile(dataset_path);
        defer file.close();

        var buffered = std.io.bufferedReader(file.reader());
        var reader = buffered.reader();

        var samples = std.ArrayList([]const u8).init(self.allocator);
        errdefer {
            for (samples.items) |s| self.allocator.free(s);
            samples.deinit();
        }

        var line_index: usize = 0;
        var loaded: usize = 0;
        const key_text = "text";

        while (true) {
            const maybe_line = reader.readUntilDelimiterOrEofAlloc(self.allocator, '\n', self.max_line_size) catch |err| {
                return err;
            };
            if (maybe_line == null) break;
            var line_buf = maybe_line.?;
            defer self.allocator.free(line_buf);

            while (line_buf.len > 0 and (line_buf[line_buf.len - 1] == '\r' or line_buf[line_buf.len - 1] == '\n')) {
                line_buf = line_buf[0 .. line_buf.len - 1];
            }

            if (line_buf.len == 0) {
                line_index += 1;
                continue;
            }

            const sample_index = loaded;
            if ((sample_index % self.coordinator.world_size) != self.coordinator.rank) {
                line_index += 1;
                continue;
            }

            const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, line_buf, .{}) catch |err| {
                _ = err;
                line_index += 1;
                continue;
            };
            defer parsed.deinit();

            if (parsed.value != .object) {
                line_index += 1;
                continue;
            }

            const obj = parsed.value.object;
            const text_value = obj.get(key_text) orelse {
                line_index += 1;
                continue;
            };

            if (text_value != .string) {
                line_index += 1;
                continue;
            }

            const text_str = text_value.string;
            if (text_str.len > self.max_text_size) {
                line_index += 1;
                continue;
            }

            const text_copy = try self.allocator.dupe(u8, text_str);
            errdefer self.allocator.free(text_copy);
            try samples.append(text_copy);
            loaded += 1;
            line_index += 1;
        }

        if (self.coordinator.isRoot()) {
            std.log.info("loaded {d} samples on rank {d}", .{ loaded, self.coordinator.rank });
        }

        return samples.toOwnedSlice();
    }

    pub fn freeDataset(self: *DistributedTrainerFuthark, samples: [][]const u8) void {
        for (samples) |s| {
            self.allocator.free(s);
        }
        self.allocator.free(samples);
    }

    pub fn trainEpoch(self: *DistributedTrainerFuthark, samples: [][]const u8) !f32 {
        if (samples.len == 0) return error.NoTrainingData;
        if (self.local_batch_size == 0) return error.InvalidBatchSize;

        var total_loss_weighted: f64 = 0.0;
        var total_weight: f64 = 0.0;

        var batch_start: usize = 0;
        while (batch_start < samples.len) {
            const batch_end = @min(batch_start + self.local_batch_size, samples.len);
            const batch = samples[batch_start..batch_end];
            const batch_count: usize = batch.len;

            const step_loss = self.trainStepFuthark(batch) catch |err| {
                try self.coordinator.abort();
                return err;
            };

            if (!std.math.isFinite(step_loss)) {
                try self.coordinator.abort();
                return error.NonFiniteLoss;
            }

            total_loss_weighted += @as(f64, step_loss) * @as(f64, @floatFromInt(batch_count));
            total_weight += @as(f64, @floatFromInt(batch_count));

            if (self.log_interval > 0 and (self.global_step % self.log_interval) == 0) {
                if (self.coordinator.isRoot()) {
                    std.log.info("step {d} loss {d:.6}", .{ self.global_step, step_loss });
                }
            }

            self.global_step += 1;
            batch_start = batch_end;
        }

        if (total_weight <= 0.0) return error.NoTrainingData;

        const loss_and_weight_f32 = [LOSS_BUFFER_ITEMS]f32{
            @floatCast(total_loss_weighted),
            @floatCast(total_weight),
        };

        try self.coordinator.copyHostToDevice(self.loss_buffer_bytes, std.mem.asBytes(&loss_and_weight_f32), self.loss_buffer_bytes.len);
        try self.coordinator.synchronize();
        try self.coordinator.allReduceFloat32(self.loss_buffer_bytes, self.loss_buffer_bytes, LOSS_BUFFER_ITEMS);
        try self.coordinator.synchronize();

        var reduced_buffer: [LOSS_BUFFER_ITEMS]f32 = undefined;
        try self.coordinator.copyDeviceToHost(std.mem.asBytes(&reduced_buffer), self.loss_buffer_bytes, self.loss_buffer_bytes.len);
        try self.coordinator.synchronize();

        const global_loss_sum: f32 = reduced_buffer[0];
        const global_weight_sum: f32 = reduced_buffer[1];

        if (!std.math.isFinite(global_loss_sum) or !std.math.isFinite(global_weight_sum) or global_weight_sum <= 0.0) {
            return error.InvalidAggregatedLoss;
        }

        const avg = global_loss_sum / global_weight_sum;

        try self.coordinator.barrier();

        return avg;
    }

    fn trainStepFuthark(self: *DistributedTrainerFuthark, batch: [][]const u8) !f32 {
        if (batch.len == 0) return error.EmptyBatch;

        var arena = std.heap.ArenaAllocator.init(self.allocator);
        defer arena.deinit();
        const arena_allocator = arena.allocator();

        var token_lists = std.ArrayList(std.ArrayList(u32)).init(arena_allocator);
        var max_seq_len: usize = 0;

        for (batch) |text| {
            var token_list = std.ArrayList(u32).init(arena_allocator);
            self.tokenizer.encode(text, &token_list) catch |err| {
                try self.coordinator.abort();
                return err;
            };
            if (token_list.items.len > max_seq_len) max_seq_len = token_list.items.len;
            try token_lists.append(token_list);
        }

        if (max_seq_len == 0) return error.EmptyTokenSequence;

        const batch_count = batch.len;

        const total_tokens = std.math.mul(usize, batch_count, max_seq_len) catch return error.InvalidDimensions;
        const token_bytes = std.math.mul(usize, total_tokens, @sizeOf(u32)) catch return error.InvalidDimensions;
        const buffer_bytes = std.math.mul(usize, token_bytes, 2) catch return error.InvalidDimensions;

        if (buffer_bytes == 0) return error.InvalidDimensions;
        if ((buffer_bytes % @sizeOf(u32)) != 0) return error.InvalidDimensions;

        var pinned_mem = PinnedMemory.alloc(buffer_bytes) catch |err| {
            if (err == error.OutOfMemory) return error.GpuMemoryLimitExceeded;
            return err;
        };
        defer pinned_mem.free();

        const full_slice = pinned_mem.asSlice(u32) orelse return error.AllocationFailed;
        const expected_len = total_tokens * 2;
        if (full_slice.len < expected_len) return error.AllocationFailed;

        const input_tokens = full_slice[0..total_tokens];
        const target_tokens = full_slice[total_tokens..expected_len];

        @memset(input_tokens, self.pad_id);
        @memset(target_tokens, self.pad_id);

        for (token_lists.items, 0..) |token_list, i| {
            const list = token_list.items;
            const offset = std.math.mul(usize, i, max_seq_len) catch return error.InvalidDimensions;

            if (list.len > 0) {
                const end_offset = std.math.add(usize, offset, list.len) catch return error.InvalidDimensions;
                if (end_offset > total_tokens) return error.InvalidDimensions;
                @memcpy(input_tokens[offset..end_offset], list);
            }
        }

        for (0..batch_count) |b| {
            const base = std.math.mul(usize, b, max_seq_len) catch return error.InvalidDimensions;
            const list_len = token_lists.items[b].items.len;

            var s: usize = 0;
            while (s + 1 < list_len) : (s += 1) {
                const src_idx = std.math.add(usize, base, s + 1) catch return error.InvalidDimensions;
                const dst_idx = std.math.add(usize, base, s) catch return error.InvalidDimensions;
                if (src_idx >= total_tokens or dst_idx >= total_tokens) return error.InvalidDimensions;
                target_tokens[dst_idx] = input_tokens[src_idx];
            }
            if (list_len > 0) {
                const last_idx = std.math.add(usize, base, list_len - 1) catch return error.InvalidDimensions;
                if (last_idx >= total_tokens) return error.InvalidDimensions;
                target_tokens[last_idx] = self.pad_id;
            }
        }

        const loss_f32 = self.accelerator.trainingStepIndices(
            input_tokens,
            target_tokens,
            batch_count,
            max_seq_len,
            self.learning_rate,
            self.momentum,
        ) catch |err| {
            try self.coordinator.abort();
            return err;
        };

        try self.accelerator.sync();

        const weights_s_ptr = self.accelerator.getWeightsSDataPointer() catch |err| {
            try self.coordinator.abort();
            return err;
        };
        const weights_t_ptr = self.accelerator.getWeightsTDataPointer() catch |err| {
            try self.coordinator.abort();
            return err;
        };

        const weight_count = std.math.mul(usize, self.model_dim, self.model_dim) catch return error.ModelDimTooLarge;

        try self.coordinator.allReduceFloat16(weights_s_ptr, weights_s_ptr, weight_count);
        try self.coordinator.allReduceFloat16(weights_t_ptr, weights_t_ptr, weight_count);
        try self.coordinator.synchronize();

        const world_size_f64: f64 = @floatFromInt(self.coordinator.world_size);
        const scale_f64: f64 = 1.0 / world_size_f64;
        const scale_f16: f16 = @floatCast(scale_f64);
        if (scale_f16 <= @as(f16, 0.0) or !std.math.isFinite(scale_f16)) return error.ScaleUnderflow;

        try self.accelerator.scaleWeights(scale_f16);
        try self.accelerator.sync();

        return loss_f32;
    }

    fn safeMakeDirForPath(allocator: std.mem.Allocator, path: []const u8) !void {
        const dir = std.fs.path.dirname(path) orelse ".";
        const real_path = try std.fs.realpathAlloc(allocator, dir);
        defer allocator.free(real_path);
        try std.fs.cwd().makePath(real_path);
    }

    fn createTempSiblingPath(allocator: std.mem.Allocator, path: []const u8) ![]u8 {
        const dir = std.fs.path.dirname(path) orelse ".";
        const base = std.fs.path.basename(path);

        var seed_buf: [8]u8 = undefined;
        std.crypto.random.bytes(&seed_buf);
        const seed = std.mem.readInt(u64, &seed_buf, .little);

        var rng = std.rand.DefaultPrng.init(seed);
        const r = rng.random().int(u64);

        if (dir.len == 0 or std.mem.eql(u8, dir, ".")) {
            return std.fmt.allocPrint(allocator, ".{s}.tmp.{x}", .{ base, r });
        } else {
            return std.fmt.allocPrint(allocator, "{s}{c}.{s}.tmp.{x}", .{ dir, std.fs.path.sep, base, r });
        }
    }

    pub fn saveCheckpoint(self: *DistributedTrainerFuthark, path: []const u8) !void {
        try self.validatePathPolicy(path);

        try self.coordinator.barrier();
        try self.accelerator.sync();
        try self.coordinator.synchronize();

        if (!self.coordinator.isRoot()) {
            try self.coordinator.barrier();
            return;
        }

        try safeMakeDirForPath(self.allocator, path);

        const tmp_path = try createTempSiblingPath(self.allocator, path);
        defer self.allocator.free(tmp_path);

        var file = std.fs.cwd().createFile(tmp_path, .{
            .read = false,
            .truncate = true,
            .exclusive = true,
        }) catch |err| {
            return err;
        };
        defer file.close();

        if (std.fs.has_executable_bit) {
            try file.chmod(DEFAULT_CHECKPOINT_PERMS);
        }

        var buffered_writer = std.io.bufferedWriter(file.writer());
        var writer = buffered_writer.writer();

        try writer.writeInt(u32, CHECKPOINT_MAGIC, .little);
        try writer.writeInt(u32, self.checkpoint_version, .little);

        if (self.global_step > std.math.maxInt(u64)) return error.StepTooLarge;
        try writer.writeInt(u64, @as(u64, @intCast(self.global_step)), .little);

        if (self.model_dim > std.math.maxInt(u64)) return error.ModelDimTooLarge;
        try writer.writeInt(u64, @as(u64, @intCast(self.model_dim)), .little);

        const lr_bits: u32 = @bitCast(self.learning_rate);
        try writer.writeInt(u32, lr_bits, .little);

        const mom_bits: u32 = @bitCast(self.momentum);
        try writer.writeInt(u32, mom_bits, .little);

        try writer.writeInt(u32, self.pad_id, .little);

        const vocab_len_usize = self.tokenizer.vocab.len;
        if (vocab_len_usize > std.math.maxInt(u32)) return error.VocabTooLarge;
        const vocab_count: u32 = @intCast(vocab_len_usize);
        try writer.writeInt(u32, vocab_count, .little);

        for (self.tokenizer.vocab) |w| {
            if (w.len > std.math.maxInt(u32)) return error.TokenTooLong;
            const n: u32 = @intCast(w.len);
            try writer.writeInt(u32, n, .little);
            try writer.writeAll(w);
        }

        const anchors_len_usize = self.tokenizer.anchors.len;
        if (anchors_len_usize > std.math.maxInt(u32)) return error.AnchorsTooLarge;
        const anchors_count: u32 = @intCast(anchors_len_usize);
        try writer.writeInt(u32, anchors_count, .little);

        for (self.tokenizer.anchors) |a| {
            if (a.len > std.math.maxInt(u32)) return error.AnchorTooLong;
            const n: u32 = @intCast(a.len);
            try writer.writeInt(u32, n, .little);
            try writer.writeAll(a);
        }

        const weight_count = std.math.mul(usize, self.model_dim, self.model_dim) catch return error.ModelDimTooLarge;
        const s_weights_flat = try self.allocator.alloc(f16, weight_count);
        defer self.allocator.free(s_weights_flat);
        const t_weights_flat = try self.allocator.alloc(f16, weight_count);
        defer self.allocator.free(t_weights_flat);

        try self.accelerator.getWeightsSFlat(s_weights_flat);
        try self.accelerator.getWeightsTFlat(t_weights_flat);

        try writer.writeAll(std.mem.sliceAsBytes(s_weights_flat));
        try writer.writeAll(std.mem.sliceAsBytes(t_weights_flat));

        try buffered_writer.flush();
        try file.sync();

        file.close();

        const dir_path = std.fs.path.dirname(path) orelse ".";
        var dir = try std.fs.cwd().openDir(dir_path, .{});
        defer dir.close();
        try dir.sync();

        std.fs.cwd().deleteFile(path) catch {};

        try std.fs.cwd().rename(tmp_path, path);

        std.log.info("checkpoint saved to '{s}' at step {d}", .{ path, self.global_step });

        try self.coordinator.barrier();
    }

    pub fn loadCheckpoint(self: *DistributedTrainerFuthark, path: []const u8) !void {
        try self.validatePathPolicy(path);

        try self.coordinator.barrier();
        try self.coordinator.synchronize();

        var root_err: ?anyerror = null;
        var status: u8 = 0;

        const weight_count = std.math.mul(usize, self.model_dim, self.model_dim) catch return error.ModelDimTooLarge;

        var s_weights: []f16 = try self.allocator.alloc(f16, weight_count);
        errdefer self.allocator.free(s_weights);
        var t_weights: []f16 = try self.allocator.alloc(f16, weight_count);
        errdefer self.allocator.free(t_weights);

        var loaded_step: u64 = 0;
        var loaded_lr: f32 = 0.0;
        var loaded_mom: f32 = 0.0;

        if (self.coordinator.isRoot()) {
            const read_ok = blk: {
                var file = std.fs.cwd().openFile(path, .{ .mode = .read_only }) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                defer file.close();

                var buffered = std.io.bufferedReader(file.reader());
                var reader = buffered.reader();

                const magic = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                if (magic != CHECKPOINT_MAGIC) {
                    root_err = error.CheckpointMagicMismatch;
                    break :blk false;
                }

                const version = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                if (version != self.checkpoint_version) {
                    root_err = error.CheckpointVersionMismatch;
                    break :blk false;
                }

                loaded_step = reader.readInt(u64, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                if (loaded_step > std.math.maxInt(usize)) {
                    root_err = error.StepTooLarge;
                    break :blk false;
                }

                const saved_model_dim = reader.readInt(u64, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                if (saved_model_dim > std.math.maxInt(usize)) {
                    root_err = error.ModelDimTooLarge;
                    break :blk false;
                }
                const saved_model_dim_usize: usize = @intCast(saved_model_dim);
                if (saved_model_dim_usize != self.model_dim) {
                    root_err = error.ModelDimMismatch;
                    break :blk false;
                }

                const lr_bits = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                loaded_lr = @bitCast(lr_bits);

                const mom_bits = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                loaded_mom = @bitCast(mom_bits);

                if (@isNan(loaded_lr) or !std.math.isFinite(loaded_lr) or loaded_lr <= 0) {
                    root_err = error.InvalidLearningRate;
                    break :blk false;
                }
                if (@isNan(loaded_mom) or !std.math.isFinite(loaded_mom) or loaded_mom < 0 or loaded_mom >= 1.0) {
                    root_err = error.InvalidMomentum;
                    break :blk false;
                }

                _ = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };

                const vocab_count = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                const vocab_count_usize: usize = @intCast(vocab_count);
                if (vocab_count_usize != self.tokenizer.vocab.len) {
                    root_err = error.VocabMismatch;
                    break :blk false;
                }

                for (self.tokenizer.vocab, 0..) |expected_token, vi| {
                    const n = reader.readInt(u32, .little) catch |err| {
                        root_err = err;
                        break :blk false;
                    };
                    const n_usize: usize = @intCast(n);
                    if (n_usize != expected_token.len) {
                        root_err = error.VocabMismatch;
                        break :blk false;
                    }
                    var tmp = self.allocator.alloc(u8, n_usize) catch |err| {
                        root_err = err;
                        break :blk false;
                    };
                    defer self.allocator.free(tmp);
                    reader.readNoEof(tmp) catch |err| {
                        root_err = err;
                        break :blk false;
                    };
                    if (!std.mem.eql(u8, tmp, expected_token)) {
                        root_err = error.VocabMismatch;
                        break :blk false;
                    }
                    _ = vi;
                }

                const anchors_count = reader.readInt(u32, .little) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                const anchors_count_usize: usize = @intCast(anchors_count);
                if (anchors_count_usize != self.tokenizer.anchors.len) {
                    root_err = error.AnchorsMismatch;
                    break :blk false;
                }

                for (self.tokenizer.anchors, 0..) |expected_anchor, ai| {
                    const n = reader.readInt(u32, .little) catch |err| {
                        root_err = err;
                        break :blk false;
                    };
                    const n_usize: usize = @intCast(n);
                    if (n_usize != expected_anchor.len) {
                        root_err = error.AnchorsMismatch;
                        break :blk false;
                    }
                    var tmp = self.allocator.alloc(u8, n_usize) catch |err| {
                        root_err = err;
                        break :blk false;
                    };
                    defer self.allocator.free(tmp);
                    reader.readNoEof(tmp) catch |err| {
                        root_err = err;
                        break :blk false;
                    };
                    if (!std.mem.eql(u8, tmp, expected_anchor)) {
                        root_err = error.AnchorsMismatch;
                        break :blk false;
                    }
                    _ = ai;
                }

                reader.readNoEof(std.mem.sliceAsBytes(s_weights)) catch |err| {
                    root_err = err;
                    break :blk false;
                };
                reader.readNoEof(std.mem.sliceAsBytes(t_weights)) catch |err| {
                    root_err = err;
                    break :blk false;
                };

                break :blk true;
            };

            if (!read_ok) {
                status = 1;
            }
        }

        var status_buf = [1]u8{status};
        try self.coordinator.broadcast(status_buf[0..], 0);
        status = status_buf[0];

        if (status != 0) {
            if (self.coordinator.isRoot()) {
                if (root_err) |e| {
                    return e;
                }
            }
            return error.CheckpointLoadFailed;
        }

        var step_buf: [8]u8 = undefined;
        if (self.coordinator.isRoot()) {
            std.mem.writeInt(u64, &step_buf, loaded_step, .little);
        }
        try self.coordinator.broadcast(step_buf[0..], 0);
        loaded_step = std.mem.readInt(u64, &step_buf, .little);

        var lr_buf: [4]u8 = undefined;
        if (self.coordinator.isRoot()) {
            std.mem.writeInt(u32, &lr_buf, @bitCast(loaded_lr), .little);
        }
        try self.coordinator.broadcast(lr_buf[0..], 0);
        loaded_lr = @bitCast(std.mem.readInt(u32, &lr_buf, .little));

        var mom_buf: [4]u8 = undefined;
        if (self.coordinator.isRoot()) {
            std.mem.writeInt(u32, &mom_buf, @bitCast(loaded_mom), .little);
        }
        try self.coordinator.broadcast(mom_buf[0..], 0);
        loaded_mom = @bitCast(std.mem.readInt(u32, &mom_buf, .little));

        try self.coordinator.broadcast(std.mem.sliceAsBytes(s_weights), 0);
        try self.coordinator.broadcast(std.mem.sliceAsBytes(t_weights), 0);

        if (loaded_step > std.math.maxInt(usize)) return error.StepTooLarge;
        self.global_step = @intCast(loaded_step);
        self.learning_rate = loaded_lr;
        self.momentum = loaded_mom;

        try self.accelerator.setWeightsS(s_weights, self.model_dim, self.model_dim);
        try self.accelerator.sync();
        try self.accelerator.setWeightsT(t_weights, self.model_dim, self.model_dim);
        try self.accelerator.sync();

        self.allocator.free(s_weights);
        self.allocator.free(t_weights);

        if (self.coordinator.isRoot()) {
            std.log.info("checkpoint loaded from '{s}' at step {d}", .{ path, self.global_step });
        }

        try self.coordinator.barrier();
    }
};
